Status adopt_actual_craft_stage_in_candidate(CommonStore&c,CraftJobsState&s,const CraftFacilityOccupancyContext&x,const StableId&id){try{writable(c,s,x);const auto*stage=s.stages.find(id);if(!stage||compare(stage->occurred_at,take(x.craft.clock.read_current_moment())))fail("CraftActualStageBoundaryRequired",id);const auto o=original(x,CraftOccupancyJobRef{stage->job_id});const auto*previous=last(x,o);if(previous&&previous->original_stage_result_ref&&same_source_ref(previous->original_stage_result_ref->source_ref,craft_stage_source(id))){history(x,o,previous->event_id);return common_success();}bool consumed=false;for(const auto&sid:o.craft->stage_result_refs){const auto*value=s.stages.find(sid);if(value&&!value->consumed.empty())consumed=true;}if(!consumed)return common_success();append(c,s,x,CraftOccupancyJobRef{stage->job_id},previous?CraftFacilityOccupancyKind::continues:CraftFacilityOccupancyKind::occupied,{});return common_success();}catch(Failure&e){return {false,{},std::move(e.error)};}}
Status clear_materialized_craft_in_candidate(CommonStore&c,CraftJobsState&s,const CraftFacilityOccupancyContext&x,const StableId&id){try{writable(c,s,x);const auto*r=s.completions.find(id);if(!r)fail("CraftMaterializationRequired",id);const auto o=original(x,CraftOccupancyJobRef{r->job_id});const auto*previous=last(x,o);if(!previous)fail("CraftMaterializedPlacementRequired",id);if(previous->occupancy_kind==CraftFacilityOccupancyKind::cleared){history(x,o,previous->event_id);if(!previous->clearance_result_ref||!same_source_ref(previous->clearance_result_ref->source_ref,craft_completion_source(id)))fail("ConflictingCraftClearanceReplay",id);return common_success();}append(c,s,x,CraftOccupancyJobRef{r->job_id},CraftFacilityOccupancyKind::cleared,MomentOwnerSource{craft_completion_source(id),1});return common_success();}catch(Failure&e){return {false,{},std::move(e.error)};}}
Status clear_cancelled_craft_in_candidate(CommonStore&c,CraftJobsState&s,const CraftFacilityOccupancyContext&x,const StableId&id){try{writable(c,s,x);const auto*r=take(read_craft_cancelled_for_output(x.craft,id));take(validate_craft_cancellation_materialization(x.craft,*r));const auto o=original(x,CraftOccupancyJobRef{r->job_id});const auto*previous=last(x,o);if(!previous){for(const auto&sid:o.craft->stage_result_refs){const auto*stage=s.stages.find(sid);if(!stage||!stage->consumed.empty())fail("CraftCancelledPlacementMissing",id);}return common_success();}if(previous->occupancy_kind==CraftFacilityOccupancyKind::cleared){history(x,o,previous->event_id);if(!previous->clearance_result_ref||!same_source_ref(previous->clearance_result_ref->source_ref,craft_cancelled_source(id)))fail("ConflictingCraftCancellationClearance",id);return common_success();}append(c,s,x,CraftOccupancyJobRef{r->job_id},CraftFacilityOccupancyKind::cleared,MomentOwnerSource{craft_cancelled_source(id),1});return common_success();}catch(Failure&e){return {false,{},std::move(e.error)};}}
Status place_started_repair_in_candidate(CommonStore&c,CraftJobsState&s,ItemInstancesState&i,const CraftFacilityOccupancyContext&x,const StableId&id){try{writable(c,s,x);if(!x.repair||&i!=&x.repair->items)fail("RepairOccupancyCandidateMismatch",id);const auto o=original(x,CraftOccupancyRepairRef{id});const auto&e=x.repair->elapsed;const auto*elapsed=find_fixed_elapsed(e,o.repair->action_id);const auto*action=c.action(o.repair->action_id);if(!elapsed||!action||action->kind!="repair"||action->actor_id!=o.repair->terms.worker_id||compare(elapsed->started_at,o.started)||compare(o.started,take(x.craft.clock.read_current_moment())))fail("RepairActualExecutionPlacementRequired",id);if(const auto*previous=last(x,o)){history(x,o,previous->event_id);if(previous->occupancy_kind!=CraftFacilityOccupancyKind::occupied)fail("ConflictingRepairPlacementReplay",id);return common_success();}for(const auto&v:i.repair_jobs.jobs.rows())if(v.first!=id&&v.second.terms.instance_id==o.repair->terms.instance_id&&!v.second.facility_occupancy_event_refs.empty()){const auto*last=s.facility_occupancy_events.find(v.second.facility_occupancy_event_refs.back());if(!last||last->occupancy_kind!=CraftFacilityOccupancyKind::cleared)fail("RepairItemAlreadyPlaced",id);}append(c,s,x,CraftOccupancyRepairRef{id},CraftFacilityOccupancyKind::occupied,{},&i);return common_success();}catch(Failure&e){return {false,{},std::move(e.error)};}}
Status clear_completed_repair_in_candidate(CommonStore&c,CraftJobsState&s,ItemInstancesState&i,const CraftFacilityOccupancyContext&x,const StableId&id){try{writable(c,s,x);if(!x.repair||&i!=&x.repair->items)fail("RepairOccupancyCandidateMismatch",id);const auto*r=i.repair_jobs.completions.find(id);if(!r)fail("RepairCompletedSourceRequired",id);const auto o=original(x,CraftOccupancyRepairRef{r->job_id});take(x.repair->original.validate_repair_completed_workstation_clearance(*o.repair,*r));const auto*previous=last(x,o);if(previous&&previous->occupancy_kind==CraftFacilityOccupancyKind::cleared){history(x,o,previous->event_id);if(!previous->clearance_result_ref||!same_source_ref(previous->clearance_result_ref->source_ref,repair_completed_source(id)))fail("ConflictingRepairClearanceReplay",id);return common_success();}append(c,s,x,CraftOccupancyRepairRef{r->job_id},CraftFacilityOccupancyKind::cleared,MomentOwnerSource{repair_completed_source(id),1},&i);return common_success();}catch(Failure&e){return {false,{},std::move(e.error)};}}
